    return <DemoSessionDetail threadId={threadId} messages={demoMessages} />;
  }

  // THEN do normal lab mode check for real sessions
  if (!isLabModeEnabled()) {
    return <LockedState reason="..." />;
  }

  // ... rest of existing logic
}
